package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ReferenceType_buildCanonicalName_TriageGen2Test {

    /**
     * Since buildCanonicalName is protected, we use reflection to access it.
     * We use the public static construct method to instantiate the ReferenceType.
     */
    @Test
    public void testBuildCanonicalName() throws Exception {
        // Setup dependencies
        Class<?> testClass = String.class;
        // We need a JavaType for the referenced type. 
        // SimpleType is a subclass of JavaType that is easy to instantiate.
        JavaType refType = new SimpleType(Integer.class);

        // Use the public construct method to create the instance
        // ReferenceType.construct(Class<?> cls, JavaType refType)
        ReferenceType referenceType = ReferenceType.construct(testClass, refType);

        // Access the protected method buildCanonicalName
        Method method = ReferenceType.class.getDeclaredMethod("buildCanonicalName");
        method.setAccessible(true);

        // Execute
        String result = (String) method.invoke(referenceType);

        // Verify
        // Expected format: _class.getName() + '<' + _referencedType.toCanonical()
        // String.class.getName() is "java.lang.String"
        // Integer.class.toCanonical() is "java.lang.Integer"
        String expected = "java.lang.String<java.lang.Integer>";
        assertEquals(expected, result);
    }




}

